namespace Kindred.Domain.Common;

/// <summary>
/// Identifier standard (Section 2, approved): every primary key is a UUIDv7, generated by the
/// application so it is known before the row is written and sorts by creation time.
/// </summary>
public static class Identifiers
{
    public static Guid NewId() => Guid.CreateVersion7();

    public static bool IsVersion7(Guid id) => id != Guid.Empty && id.Version == 7;
}
